var e={titulo:`KERNEL PANIC`,tagline:`Ataque Cibernético`,versus:`VERSUS`,versus_sub:`2 jugadores en el mismo dispositivo`,solo:`SOLO`,solo_sub:`Enfrenta a la IA`,dificuldade:`DIFICULTAD`,selecione_nivel:`Selecciona el nivel`,facil:`FÁCIL`,facil_sub:`IA prioriza aleatoriedad`,medio:`MEDIO`,medio_sub:`IA toma decisiones tácticas`,voltar:`← Volver`,voltar_jogos:`← Volver a Juegos`,manual:`📖 Manual`,manual_sub:`Cómo jugar`},t={ciclo:`Ciclo`,solo_facil:`SOLO FÁCIL`,solo_medio:`SOLO MEDIO`,versus:`VERSUS`},n={ciclo:`Ciclo`,operador:`Operador`,stack:`Stack`,lixo:`Descarte`},r={ciclo:`ciclo`,ciclos:`ciclos`},i={precisao:`Precisión {mod}`,visao:`Escáner {mod}`,protecao:`Blindaje {mod}`,camuflagem:`Señal Fantasma {mod}`,scan_anulado:`Escáner anulado`,blindagem_anulada:`Blindaje anulado`},a={player_prefix:`J`},o={prefix:`J`,operando:`OPERANDO`,grid:`Cuadrícula`,buffer:`Buffer`,vazio:`— vacío —`,comprado:`ROBADO`,comprar:`ROBAR`,atirar:`DISPARAR`,passar:`PASAR`},s={bloqueado:`Espacio bloqueado hasta ciclo {round}`},c={confirmar_ataque:`CONFIRMAR ATAQUE`,selecione_ataque:`Selecciona los módulos de ataque`,ataque:`Ataque`,sem_ataque:`Ningún módulo de ataque`,defesa_opcional:`Defensa (opcional)`,sem_defesa:`Ningún módulo de defensa`,efeito:`Efecto`,potencia_fogo:`Potencia de fuego:`,defesa:`Defensa:`,atirar:`DISPARAR`,cancelar:`CANCELAR`},l={titulo:`DEFENSA`,selecione_defesa:`Selecciona la defensa de J{player}`,defesa:`Defensa`,sem_defesa:`Ninguna defensa disponible`,reacao:`Reacción`,total:`Defensa total:`,confirmar:`CONFIRMAR`,cancelar:`CANCELAR`},u={titulo:`REACCIÓN`,disponivel:`Una carta de reacción está disponible`,disparar:`¿Disparar {card}?`,descricao:`Permite un segundo disparo con la mitad de generación de Exposición.`,usar:`USAR`,declinar:`DECLINAR`},d={acertou:`🚀 ACIERTO`,errou:`💥 FALLO`,decoy:`¡Ataque absorbido por el Decoy!`,calc_atk_def:`Ataque {atk} - Defensa {def} = {diff}`,calc_perigo:`+ Peligro {perigo}`,alvo:`Objetivo {target}`,rolagem_hit:`Tirada: {rolled} ≤ {target}`,rolagem_miss:`Tirada: {rolled} > {target}`,atingido:`GOLPEADO`,falhou:`FALLÓ`,continuar:`CONTINUAR`},f={vitoria:`VICTORIA`,derrota:`DERROTA`,venceu_texto:`¡Operador ganó el combate!`,perdeu_texto:`IA dominó el sistema...`,revanche:`REVANCHA`,menu:`MENÚ`},p={ok:`OK`},m={titulo:`NUEVO OPERADOR`,instrucao:`Pasa el dispositivo`,pronto:`LISTO`},h={titulo:`INTELIGENCIA`,subtitulo:`Cartas reveladas`,fechar:`CERRAR`},g={atributo:`Atributo: {attr}`,trigger:`Trigger: {trigger}`,fechar:`CERRAR`},_=JSON.parse(`{"cover":{"tag":"Manual del Operador · Versión 1.0","sub":"Protocolo de Eliminación","desc":"Un juego de cartas táctico para dos operadores\\nSistema D20 · Dos jugadores · Un terminal","badge":"Clasificación: Acceso Liberado"},"s01":{"tag":"// 01 — Briefing","title":"Qué Es Kernel Panic","p":["Kernel Panic es un juego de cartas táctico para dos jugadores, ambientado en un mundo cyberpunk donde operadores de élite se eliminan usando módulos cibernéticos, hacks y ataques de precisión neural.","Cada operador acumula módulos de ataque y defensa en su grid a lo largo de las rondas. Cuando el momento es correcto — o la presión es demasiada — se ejecuta un disparo. Un dado de veinte caras decide el destino."],"box_title":"Concepto central","box_text":"Cuanto más esperas para atacar, más Exposición acumulas — y más vulnerable te vuelves. El juego presiona a ambos lados al mismo tiempo."},"s02":{"tag":"// 02 — Infraestructura","title":"El Tablero","intro":"La mesa de juego tiene los siguientes elementos:","items":[{"accent":"atk","type":"Stack","name":"Mazo de Compra","desc":"Mazo compartido entre los dos operadores. Cuando se agota, el descarte se baraja y se convierte en un nuevo stack."},{"accent":"ter","type":"Ambiente","name":"Mazo de Terreno","desc":"Mazo separado de condiciones de combate. Cada 3 ciclos se saca una nueva carta que afecta a ambos operadores. Las cartas vuelven al mazo al expirar — nunca van al descarte."},{"accent":"efx","type":"Descarte","name":"Cementerio","desc":"Donde van los módulos usados o descartados. Compartido entre los operadores."},{"accent":"def","type":"Grid","name":"Campo de cada operador","desc":"Cada operador tiene 6 espacios en su grid. Los módulos se instalan boca abajo — el oponente no sabe lo que hay. Puedes consultar tus propios módulos en cualquier momento."}],"buf_title":"Buffer","buf_text":"La mano de cada operador. Empiezas con 5 módulos y nunca puedes tener más de 5 al final de tu ciclo."},"s03":{"tag":"// 03 — Especificaciones","title":"Atributos","intro":"Cada operador posee cuatro atributos de combate y un atributo de riesgo:","mira":{"name":"Mira Ocular","vs":"Ataque · Bloqueado por Blindaje","desc":"Implante neural de precisión. Ataque directo y calibrado."},"scan":{"name":"Escáner","vs":"Ataque · Bloqueado por Señal Fantasma","desc":"Detección electrónica del objetivo. Rastreo de posición y vulnerabilidades."},"blind":{"name":"Blindaje","vs":"Defensa · Contra Mira Ocular","desc":"Armadura cibernética. Neutraliza ataques de precisión directa."},"ghost":{"name":"Señal Fantasma","vs":"Defensa · Contra Escáner","desc":"Interferencia de rastreo. Hace invisible al operador ante los sensores enemigos."},"warn":"Blindaje solo neutraliza Mira Ocular. Señal Fantasma solo neutraliza Escáner. Combinar mal es dejar pasar el ataque.","exp":{"name":"Exposición","vs":"Riesgo · Visible para ambos operadores","desc":"Cuanto más alta la Exposición, más fácil es acertarte un tiro. Sube naturalmente cada ciclo después del tercero, y se dispara tras cualquier ataque. Gestionarla es tan importante como atacar."},"exp_title":"Mecánica de Exposición","exp_rules":["— Está en 0 los primeros 3 ciclos","— A partir del ciclo 4: sube +1 por ciclo","— Al ejecutar un ataque: +8 inmediatos, decayendo −2 por ciclo","— Si disparas y fallas, sigues expuesto. Dispara con cuidado."]},"s04":{"tag":"// 04 — Protocolo","title":"Tu Ciclo","intro":"Cada ciclo, el operador activo ejecuta las siguientes acciones — en este orden:","steps":[{"num":1,"title":"Robar — Obligatorio","desc":"Roba 1 módulo del stack. Siempre es obligatorio. Puedes robar módulos extra hasta tener 5 en el buffer — cada robo extra cuesta +1 de Exposición.","optional":false},{"num":2,"title":"Instalar — Opcional","desc":"Instala hasta 2 módulos del buffer en tu grid. Los módulos se instalan boca abajo — el oponente no sabe lo que instalaste.","optional":true},{"num":3,"title":"Activar Equipo — Opcional","desc":"Si tienes módulos de equipo instalados en el grid, puedes activarlos. Los equipos no consumen el ciclo — pueden usarse antes o después de instalar.","optional":true},{"num":4,"title":"Ejecutar Ataque — Opcional","desc":"Ejecuta un ataque contra el oponente. Elige qué módulos de ataque usar. El oponente responde con su defensa. El ataque siempre termina el ciclo.","optional":true}],"buf_title":"Límite de buffer","buf_text":"Al final del ciclo no puedes tener más de 5 módulos en el buffer. Si tienes más, descarta el excedente — o instala en el grid para no perderlos."},"s05":{"tag":"// 05 — Ejecución","title":"El Ataque","intro":"Los ataques solo pueden ejecutarse a partir del ciclo 4. Antes de eso, los operadores se están posicionando.","divider":"Flujo del ataque","steps":[{"num":1,"title":"Atacante elige los módulos","desc":"Selecciona qué módulos de Mira Ocular y Escáner de tu grid se usarán. No tienes que usar todos — elige estratégicamente."},{"num":2,"title":"Defensor elige los módulos","desc":"El defensor ve el desglose del ataque — cuánta Mira Ocular y Escáner viene — y elige qué módulos de Blindaje y Señal Fantasma usar para bloquear."},{"num":3,"title":"Resolución","desc":"El sistema calcula el resultado y lanza el D20. Los módulos usados van al descarte independientemente del resultado."}],"formula_eq":"( ATAQUE − DEFENSA ) + EXPOSICIÓN DEL OBJETIVO\\n= OBJETIVO DEL D20","formula_note":"Lanza el D20 — si el resultado es ≤ al objetivo, el ataque acierta · 20 siempre falla","neg_title":"Resultado negativo","neg_text":"Si Ataque − Defensa es negativo, el resultado se trata como cero. Pero la Exposición del defensor todavía cuenta — nunca es imposible acertar.","acerto":"Un acierto certero es letal — el operador es eliminado y la partida termina. Salvo efecto de módulo especial como el Decoy.","falha":"En caso de fallo, todos los módulos usados en el ataque y la defensa van al descarte. La Exposición del atacante aún sube."},"s06":{"tag":"// 06 — Inventario","title":"Tipos de Módulo","items":[{"accent":"atk","name":"Módulo de Ataque","desc":"Mira Ocular / Escáner. Añaden poder al ataque. Valores de +1 a +3. Van al descarte tras el ataque."},{"accent":"def","name":"Módulo de Defensa","desc":"Blindaje / Señal Fantasma. Reducen el poder del ataque recibido. Valores de +1 a +3. Solo funcionan contra el tipo correcto de ataque."},{"accent":"efx","name":"Módulo de Efecto","desc":"Decoy · Contra-Hack · Segundo Pulso. Activados automática u opcionalmente en condiciones específicas. Permanecen en el grid esperando."},{"accent":"eqp","name":"Módulo de Equipo","desc":"Virus · Spyware · DDoS · Firewall Trap · Deep Scan. Activados en tu ciclo sin costo de acción. Van al descarte tras usar."}],"efeitos_title":"Módulos de Efecto en detalle","efeitos":[{"accent":"efx","type":"Efecto · Obligatorio · Activado al ser acertado","name":"Decoy","desc":"Si el operador recibe un acierto certero, el Decoy se activa automáticamente — el ataque es absorbido. El operador sobrevive. No hay elección."},{"accent":"efx","type":"Efecto · Opcional · Tras fallo del oponente","name":"Contra-Hack","desc":"Si el oponente falla el ataque, puedes ejecutar un contraataque inmediato sin gastar tu ciclo. La Exposición sube normalmente."},{"accent":"efx","type":"Efecto · Opcional · Tras fallar tu ataque","name":"Segundo Pulso","desc":"Si fallas un ataque, puedes ejecutar un segundo ataque inmediatamente. Genera solo la mitad de Exposición. Usable una vez por secuencia."}],"equip_title":"Módulos de Equipo en detalle","equip":[{"accent":"eqp","type":"Equipo","name":"Virus","desc":"Destruye un módulo instalado en el grid del oponente. Va directo al descarte."},{"accent":"eqp","type":"Equipo · Requiere espacio en buffer","name":"Spyware","desc":"Copia un módulo del grid del oponente a tu buffer. Solo usable si tienes espacio."},{"accent":"eqp","type":"Equipo","name":"DDoS","desc":"La Exposición del oponente sube +3. La tuya sube +1. Jugada agresiva para presionar."},{"accent":"eqp","type":"Equipo","name":"Firewall Trap","desc":"Bloquea un espacio vacío del grid del oponente por 5 ciclos. El espacio queda inutilizable."},{"accent":"eqp","type":"Equipo","name":"Deep Scan","desc":"Escanea el buffer del oponente y revela 2 módulos aleatorios. Información valiosa."}]},"s07":{"tag":"// 07 — Condiciones Externas","title":"Condiciones de Terreno","intro":"Cada 3 ciclos, una nueva condición de terreno se activa y afecta a ambos operadores. Las condiciones duran 3 ciclos y luego vuelven al mazo.","items":[{"icon":"☣","name":"Lluvia Ácida","effect":"Escáner −3, Señal Fantasma +3 para ambos. Sensores comprometidos, camuflaje favorecido."},{"icon":"⚡","name":"Pulso EMP","effect":"Exposición −3 tras cualquier ataque. La descarga electromagnética dispersa señales."},{"icon":"🔆","name":"Luz Neon Intensa","effect":"Mira Ocular −3, Escáner +3 para ambos. Exceso de luz dificulta la mira directa."},{"icon":"📡","name":"Interferencia Solar","effect":"Operador aleatorio: −1 Escáner y −1 Señal Fantasma. El otro recibe +1 en ambos."},{"icon":"🌫","name":"Niebla de Datos","effect":"Señal Fantasma +2 para ambos. Ambiente digital saturado de ruido."},{"icon":"💀","name":"Blackout de Red","effect":"Anula todos los módulos de Escáner en campo. Detección electrónica comprometida."},{"icon":"🔴","name":"Sobrecarga del Sistema","effect":"Anula todos los módulos de Blindaje en campo. Armaduras cibernéticas colapsan."},{"icon":"⬜","name":"Terreno Neutral","effect":"Sin efecto. Las condiciones están estables."},{"icon":"🌑","name":"Modo Stealth","effect":"Señal Fantasma +3 para ambos. Exposición +2 adicional tras cualquier ataque."},{"icon":"💾","name":"Zona de Guerra Cyber","effect":"Exposición sube 2 puntos por ciclo en vez de 1. La presión se duplica."}]},"s08":{"tag":"// 08 — Cierre","title":"Victoria y Derrota","intro":"La partida termina cuando un operador es alcanzado por un ataque certero sin tener un Decoy instalado en el grid.","kp_title":"Kernel Panic","kp_text":"El sistema enemigo colapsó. Acceso total obtenido. Misión completada con éxito.","sf_title":"System Failure","sf_text":"Tu sistema fue comprometido. El kernel entró en pánico. No hay recuperación posible.","solo":"En modo Solitario, el operador se enfrenta a un agente de IA en dificultad Fácil o Medio. El modo Difícil está en desarrollo.","local":"En modo Red Local, dos operadores usan el mismo terminal. Una pantalla de transferencia aparece entre cada ciclo para proteger la privacidad del buffer."},"s09":{"tag":"// 09 — Inteligencia de Campo","title":"Consejos para Operadores","items":[{"accent":"atk","name":"Gestiona tu Exposición","desc":"Robar módulos extra cuesta Exposición. Atacar cuesta Exposición. Cada decisión tiene un precio."},{"accent":"def","name":"Defiende con el tipo correcto","desc":"Blindaje no bloquea Escáner. Señal Fantasma no bloquea Mira Ocular. Mira el desglose del ataque antes de elegir."},{"accent":"efx","name":"El Decoy es tu vida","desc":"Instala el Decoy en el grid lo antes posible. Se activa automáticamente — no necesitas hacer nada. Es tu única segunda oportunidad."},{"accent":"eqp","name":"Equipos cambian el juego","desc":"Un Virus en el momento justo destruye la acumulación del oponente. Deep Scan revela lo que viene. Úsalo con timing."},{"accent":"ter","name":"Lee el terreno","desc":"Sobrecarga del Sistema anula Blindaje — ataca este ciclo. Blackout de Red anula Escáner — usa solo Mira Ocular. El terreno lo cambia todo."}]},"footer":{"l1":"Kernel Panic · Manual del Operador · v1.0","l2":"Protocolo de Eliminación · Sistema D20","end":"// FIN DEL DOCUMENTO"}}`),v={titulo:`IA PROCESANDO`,baixando:`Descargando módulo...`,instalando:`Instalando módulo en la cuadrícula...`,ativando:`Activando equipamiento...`,atacando:`Iniciando ataque...`,encerrando:`Finalizando ciclo...`,exposicao:`Exposición aumentando...`,processando:`Procesando...`,algoritmo:`Ejecutando algoritmo...`},y={menu:e,global:t,infobar:n,terrain:r,terraininfo:i,perigo:a,playerpanel:o,fieldslot:s,shot:c,defense:l,reaction:u,result:d,victory:f,message:p,handoff:m,intel:h,inspect:g,manual:_,aiwait:v};export{v as aiwait,y as default,l as defense,s as fieldslot,t as global,m as handoff,n as infobar,g as inspect,h as intel,_ as manual,e as menu,p as message,a as perigo,o as playerpanel,u as reaction,d as result,c as shot,r as terrain,i as terraininfo,f as victory};
